"""Public coaching companion. Private facilitator scripts are authored separately."""
import json
from html import escape as e
from functools import partial

def build_coaching(api):
 R=api['R'];page,heading,section,link,ul=[api[k] for k in ['page','heading','section','link','ul']]
 slug='coaching-that-clicks';SP='sessions/'+slug+'/';DD='downloads/'+slug+'/';out=R/DD;out.mkdir(parents=True,exist_ok=True)
 s=next(x for x in api['DATA']['sessions'] if x['id']==slug);d=json.loads((R/'data/coaching-that-clicks.json').read_text())
 from reportlab.graphics.barcode.qr import QrCodeWidget
 from reportlab.graphics.shapes import Drawing
 from reportlab.graphics import renderSVG
 qr=QrCodeWidget('https://mglearn.github.io/tcea27/'+SP,barLevel='M');bounds=qr.getBounds();w,h=bounds[2]-bounds[0],bounds[3]-bounds[1]
 drawing=Drawing(150,150,transform=[150/w,0,0,150/h,0,0]);drawing.add(qr);renderSVG.drawToFile(drawing,str(R/'assets/images/coaching-session-qr.svg'))
 tabs=[('index.html','Home'),('learn.html','Learn'),('watch.html','Watch'),('practice.html','Practice'),('plan.html','Plan'),('reflect.html','Reflect'),('resources.html','Resources')]
 def show(file,title,body):
  nav='<nav class="session-nav" aria-label="Coaching session"><div class="container">'+''.join('<a href="'+p+'"'+(' aria-current="page"' if p==file else '')+'>'+label+'</a>' for p,label in tabs)+'</div></nav>'
  page(SP+file,title,nav+body,'sessions')
 def cards(items):return '<div class="grid">'+''.join('<article class="card"><h3>'+e(h)+'</h3><p>'+e(t)+'</p></article>' for h,t in items)+'</div>'
 def form(id,fields):
  return '<form class="reflection coaching-notes" id="'+id+'"><p>Use generic examples only. Do not enter student information, classroom recordings, or identifiable teacher records. Notes stay in this page’s memory; copy, download, or print before leaving. Reloading clears them.</p>'+''.join('<label for="'+id+'-'+str(i)+'">'+e(label)+'</label><textarea id="'+id+'-'+str(i)+'" data-label="'+e(label)+'" maxlength="3000" autocomplete="off"></textarea>' for i,label in enumerate(fields))+'<div class="actions"><button type="button" data-coaching="copy">Copy notes</button><button type="button" data-coaching="download">Download notes</button><button type="button" data-coaching="print">Print notes</button><button type="reset" class="button ghost">Clear notes</button></div><p role="status" aria-live="polite"></p></form>'
 evidence='<div class="callout"><h2>Research foundation</h2><p><strong>0.86 weighted mean effect size</strong> · 5 meta-analyses · 270 studies · 307 effects.</p><p>Visible Learning MetaX version 1.4, updated February 2026; verified October 28, 2026. The TCEA article cited 0.99; this companion uses the current MetaX value. These findings summarize studies across settings and outcomes. They do not guarantee school results or predict an individual teacher’s growth.</p>'+link(d['sources'][2]['url'],'Read the MetaX research record','',True)+'</div>'
 eiir='<img src="@@assets/infographics/coaching-eiir.svg" width="1100" height="260" alt="Empower: choose a goal; Implement: record practice; Investigate: review evidence; Realize: test and revisit" style="width:100%;height:auto">'+cards([('Empower','Teacher chooses a meaningful instructional goal. What do you want to learn about your teaching?'),('Implement','Record a focused segment. What instructional moment should we examine?'),('Investigate','Review the evidence together. What patterns do we notice?'),('Realize','Identify growth and next steps. What might you try next, and how will you review the results?')])
 trust='<h2>Trust comes before the camera</h2>'+ul(['Teacher participation, voice, and ownership','Agree on a narrow goal and who may view the recording','Follow district recording, consent, access, storage, and deletion policies','Separate coaching from formal evaluation wherever district policy permits','Make only confidentiality commitments that policy can support','Let the teacher review privately before a shared conversation'])
 protocol='<img src="@@assets/infographics/coaching-protocol.svg" width="1100" height="260" alt="Notice: describe evidence; Wonder: explore questions; Next: agree on a test" style="width:100%;height:auto">'+cards([('Notice · What happened?','Describe observable teacher and student behavior. “I noticed the teacher paused before inviting a response.”'),('Wonder · What questions arise?','Explore interpretations and missing evidence. “I wonder how that thinking time affected student responses.”'),('Next · What might we test?','Agree on one manageable change and evidence. “What if students wrote first? How would we know whether it helped?”')])
 agenda='<ol class="agenda">'+''.join('<li><time>'+str(a['start'])+'–'+str(a['end'])+' min</time><div><strong>'+e(a['title'])+'</strong><p>'+e(a['description'])+'</p></div></li>' for a in d['agenda'])+'</ol>'
 show('index.html',s['title'],heading('Instructional coaching',s['title'],s['subtitle'])+section('<div class="split"><div class="prose"><p>'+e(s['fullDescription'])+'</p><p><strong>Miguel Guhlin · TCEA · 50 minutes</strong></p><p>Presenter-led video observation, individual reflection, nearby partner conversation, and practical application. No accounts, preparation, or participant devices required. Theater seating works.</p><div class="actions">'+link('watch.html','Start with classroom evidence')+link('resources.html','Get the materials','button ghost')+'</div><h2>Learning outcomes</h2>'+ul(s['learningObjectives'])+'<h2>What success looks like</h2>'+ul(s['successCriteria'])+'</div><aside class="card"><h2>Our fifty-minute route</h2>'+agenda+'</aside></div><img src="@@'+s['image']+'" width="1400" height="788" alt="'+s['imageAlt']+'" style="width:100%;height:auto;border-radius:18px"><p class="small muted">AI-generated illustrative coaching scene; not an actual classroom observation.</p>'))
 moves=[('Know your learners','Ask about coaching responsibilities, concerns, and what would be useful.'),('Decide what matters most','Use classroom evidence to support one reflective coaching conversation.'),('Create connections','Connect prior experiences through short, structured nearby conversations.'),('Show and practice','Model Notice-Wonder-Next, then let colleagues try it.'),('Build in reflection','Make room for quiet observation and thinking before discussion.'),('Plan for changed practice','Choose a specific action and a date to revisit it.')]
 show('learn.html','Micro-teaching and trust',heading('Learn','From “I feel” to “I see.”','A shared record helps teachers and coaches examine the same classroom moment.')+section('<div class="prose"><h2>What is micro-teaching?</h2><p>Teach and record a short segment, examine it against a goal, discuss evidence, test a small adjustment, and review the results. Ask who answered, how much thinking time was available, and what students actually demonstrated.</p><p>Engagement impressions alone do not establish understanding. Video helps us revisit instructional decisions with curiosity.</p></div>'+eiir+trust+evidence)+section('<h2>Professional learning that makes a difference</h2><p>Dr. Glenda Horner’s central advice: keep the session focused. Experience one observation and practice one protocol.</p>'+cards(moves)+'<p>These six moves synthesize the published facilitation notes and accompanying reflection; they are not a verbatim transcription of the infographic.</p><div class="actions">'+link(d['sources'][3]['url'],'Read the podcast reflection','button ghost',True)+link(d['sources'][4]['url'],'Open the facilitator infographic','button ghost',True)+link(d['sources'][5]['url'],'Listen to Forward Thinking','button ghost',True)+'</div>','pale'))
 backup='<details id="video-backup"><summary>Video unavailable? Use this fictional classroom case.</summary><p>A middle school science teacher asks a question and calls on the first raised hand. The student answers correctly. The same student answers the next question. Later the teacher asks whether everyone understands; several students nod. The teacher moves on.</p><h3>Notice</h3><p>We heard answers from one student, not responses from everyone.</p><h3>Wonder</h3><p>How could the teacher find out whether the other students understood?</p><h3>Next</h3><p>Ask every student to write a response before inviting individual answers.</p><p>This fictional stimulus preserves conversation practice when video fails. It does not provide the evidence available in an actual recording.</p></details>'
 show('watch.html','Observe classroom evidence',heading('Watch','What do you actually see?','How does wait time influence opportunities for student thinking and participation?')+section('<div class="prose"><h2>Wait Time – Secondary: Phil Fowkes at Reach Academy</h2><p>Department for Education, England · Secondary classroom · Questioning and thinking time.</p><p>Open the original video in a separate tab. No third-party player or cookies load on this page.</p><div class="actions">'+link(d['sources'][1]['url'],'Watch the secondary wait-time example ↗','button',True)+link('https://youtu.be/c1AJi3ALiws','Open the audio-described version ↗','button ghost',True)+'</div><p>The official resource includes a video transcript. Preview before the conference and choose approximately two minutes containing questions and responses; confirm exact start/end points, audio, captions, and accessible alternatives. No excerpt timing is claimed here.</p><h2>Watch → think → compare</h2><ol><li>Set the question (1 minute).</li><li>Watch the selected excerpt (about 2 minutes).</li><li>Record two observations silently (1 minute).</li><li>Compare with a nearby partner (2 minutes).</li><li>Debrief evidence versus interpretation (3 minutes).</li></ol><p><strong>Observe:</strong> teacher questions, pauses, student responses, and follow-up questions.</p><p><strong>Evidence:</strong> “The teacher paused before inviting a response.” <strong>Interpretation:</strong> “Students were more engaged because the teacher waited.” The latter requires additional evidence.</p><p>Examine instructional decisions with curiosity. This is practice observing evidence, not grading the recorded teacher.</p>'+backup+'<h2>Alternative classroom examples</h2><ul><li>'+link('https://www.youtube.com/watch?v=r2cXXSKa0Vw','Check Whole Class Understanding – Secondary at Reach Academy','',True)+' · What evidence of understanding does the teacher gather?</li><li>'+link('https://www.youtube.com/watch?v=r8RlvU-C0yo','Wait Time – Primary at Reach Academy','',True)+' · What opportunities do pupils have to prepare an answer?</li></ul>'+link(d['sources'][6]['url'],'Read the official video collection and transcript','button ghost',True)+'<p>Link to original sources. Preview each selected clip; verify accessibility and playback. Do not upload or redistribute recordings without appropriate permission.</p><div class="actions">'+link('practice.html','Record observations and practice coaching')+'</div></div>'))
 conversation=[('Coach','When you watched the clip, what stood out?'),('Teacher','I noticed I gave students time to think before asking for an answer.'),('Coach','What did you notice about how students used that time?'),('Teacher','Some appeared to prepare a response. I’d like to know whether more were ready.'),('Coach','What might help you gather that evidence?'),('Teacher','I could ask students to write before choosing someone to respond.'),('Coach','What would you look for to decide whether that helped?'),('Teacher','The number producing a response and the quality of their explanations.'),('Coach','When would you like to try it?')]
 comparison=[('You talked too much.','What do you notice about the balance of teacher and student talk?'),('Students weren’t engaged.','What evidence do we have about student participation?'),('Your questioning needs improvement.','Which questions produced useful student responses?'),('You should wait longer.','What might change with more thinking time?'),('You need to involve more students.','How might you gather responses from more students?')]
 show('practice.html','Notice, Wonder, Next',heading('Practice','Notice. Wonder. Next.','Move from observable evidence to inquiry and one manageable action.')+section(protocol+form('coaching-observe',['Notice: two specific teacher or student behaviors','Wonder: one question that invites reflection','What additional evidence would help?','Next: one possible adjustment','How would we know whether it helped?'])+'<h2>Try the conversation with a neighbor</h2><p>Take the coach role for two minutes, then switch for two minutes. Ask questions grounded in the shared example. Which question encouraged reflection rather than defense?</p><details><summary>Read a model coaching conversation</summary>'+''.join('<p><strong>'+who+':</strong> '+e(line)+'</p>' for who,line in conversation)+'</details><h2>Change the feedback</h2><div class="table-wrap"><table><thead><tr><th scope="col">Evaluative statement</th><th scope="col">Reflective question</th></tr></thead><tbody>'+''.join('<tr><td>'+e(a)+'</td><td>'+e(b)+'</td></tr>' for a,b in comparison)+'</tbody></table></div><p>Begin with teacher reflection, recognize strengths, avoid blame and personal judgments, and agree on follow-up. Questions alone cannot meet every need: offer direct information, modeling, resources, or explicit feedback when useful.</p>'))
 sprint=[('Choose a teacher-directed goal','Participation, questioning, thinking time, understanding, or student explanations.'),('Record a short segment','Begin with approximately 10–15 minutes, following the TCEA article and district requirements.'),('Review the evidence','Teacher watches privately first; examine relevant moments together.'),('Discuss one improvement','Use Notice-Wonder-Next to select a manageable adjustment.'),('Test the adjustment','Try it in a subsequent lesson.'),('Review the results','Compare evidence: what changed, improved, remains uncertain, or needs another attempt?')]
 show('plan.html','Start a micro-coaching sprint',heading('Plan','Start small. Look again.','One goal, one short teaching segment, one thoughtful conversation.')+section(cards(sprint)+trust+'<h2>Before, during, and after</h2><p>Before recording, agree on why the goal matters, what success would look like, what to capture, access, deletion, and a conversation date. Capture only the evidence needed. Before meeting, invite the teacher to identify a strength, an interesting pattern, and a question.</p><p>During the conversation, start with the teacher’s interpretation. Afterward, agree on one adjustment, when to test it, evidence to collect, and a follow-up date. Revisit the goal and compare what happened.</p><div class="callout"><h3>A possible sprint</h3><p>Focus: participation during questioning. Evidence: the number of students producing a response and the quality of explanations. Change: individual thinking and writing before sharing. Follow-up: record a comparable segment and examine the same evidence.</p></div>'+form('coaching-plan',['Instructional practice and teacher-selected goal','What evidence would you collect?','What small adjustment could the teacher test?','Recording access, consent, retention, and deletion arrangements','When will the teacher try it?','How and when will you review the evidence?'])+eiir))
 show('reflect.html','ACE reflection',heading('Reflect','What will be different?','Return to the teacher and coach who remember the same lesson differently.')+section(cards([('Articulate','How can micro-teaching help a teacher understand what happened?'),('Connect','How could Notice-Wonder-Next fit your current coaching conversations?'),('Extend','What will you change in one conversation in the next two weeks?')])+form('coaching-ace',['Articulate: explain the central idea in your own words','Connect: relate the protocol to your current practice','Extend: choose one action in the next two weeks','When will you revisit it, and what evidence will you use?'])+'<p class="prompt">What evidence would help the teacher and coach move forward together?</p><p>Start with a willing teacher, a narrow goal, clear safeguards, and a short observation. Test one small change, then look again.</p>'))
 blocks={
 'observation-guide':('Micro-teaching observation guide',[('Before watching','Video: Wait Time – Secondary: Phil Fowkes at Reach Academy. Focus: questioning, thinking time, and student participation. What would help us understand whether students had time to think?'),('Notice: what happened?','Observation 1: __________________________________________\nObservation 2: __________________________________________\nWhat did the teacher and students say or do? What can you verify?'),('Wonder: what questions arise?','I wonder: ______________________________________________\nAdditional evidence needed: ______________________________'),('Next: what could be tried?','One possible adjustment: _________________________________\nEvidence to collect: ______________________________________'),('Reflect','What did video help you notice that you might miss in real time? Which question encouraged reflection?')]),
 'coaching-protocol':('Notice, Wonder, Next quick reference',[('Notice: evidence','What do you notice? What stands out? What did students do? Which patterns connect to the goal?'),('Wonder: inquiry','What might explain this? What surprised you? What other perspectives or evidence should we consider?'),('Next: action','What might you try? What support would help? How will we know whether it helped? When will we revisit?'),('Do','Begin with teacher reflection; recognize strengths; describe evidence; invite teacher ideas; agree on follow-up.'),('Avoid','Lists of mistakes, treating interpretations as facts, judging appearance, comparing teachers, unsupported confidentiality promises, or ending without a next step.'),('Choose the support needed','Sometimes direct information, modeling, resources, and explicit feedback help more than another question.')]),
 'sprint-template':('Micro-coaching sprint planning template',[(h,t+'\n________________________________________________________\n________________________________________________________') for h,t in sprint]+[('Recording agreement','Confirm teacher ownership, consent, access, storage, retention, deletion, and evaluation boundaries with district policy.'),('Follow-through','Test date: __________________ Follow-up date: __________________\nEvidence and review method: _________________________________')]),
 'ace-reflection':('ACE coaching reflection',[('Articulate','How does micro-teaching help us understand what happened?\n________________________________________________________\n________________________________________________________'),('Connect','Where does Notice-Wonder-Next fit your practice?\n________________________________________________________\n________________________________________________________'),('Extend','What will you change in one conversation in the next two weeks?\n________________________________________________________\n________________________________________________________'),('Commit and revisit','I will try: _______________________________________________\nBy: __________________ Evidence: _________________________\nReview date: ____________________________________________')]),
 'session-submission':('Conference session submission',[('Title',s['title']),('Subtitle',s['subtitle']),('Description',s['fullDescription']),('Learning outcomes','\n'.join(s['learningObjectives'])),('Audience',', '.join(s['audience'])),('Requirements','50 minutes; theater-style seating or rows. Presenter computer, projector, audio, and internet. Participant devices optional. Nearby conversations, digital observation guide, optional print copies. No accounts, preparation, or advance registration required.'),('Format',s['format']+' with video observation, individual reflection, partner conversations, and practical application.')])}
 from reportlab.platypus import SimpleDocTemplate,Spacer
 from reportlab.pdfgen import canvas
 docs=''
 for key,(title,parts) in blocks.items():
  story=[api['para']('TCEA 2027 | MIGUEL GUHLIN / MG Learn','Small27'),api['para'](title,'Title27')];html=''
  for sub,text in parts:
   story.append(api['para'](sub,'Section27'));html+='<h2>'+e(sub)+'</h2>'
   for line in text.split('\n'):story.append(api['para'](line));html+='<p>'+e(line)+'</p>'
  story+=[Spacer(1,12),api['para']('Original materials by Miguel Guhlin / MG Learn. Reuse and adapt with attribution. TCEA 2027.\nhttps://mglearn.github.io/tcea27/'+SP,'Small27')]
  SimpleDocTemplate(str(out/(key+'.pdf')),pagesize=(612,792),rightMargin=45,leftMargin=45,topMargin=42,bottomMargin=50,title=title,author='Miguel Guhlin / MG Learn',invariant=1).build(story,onFirstPage=api['footer'],onLaterPages=api['footer'],canvasmaker=partial(canvas.Canvas,invariant=1))
  page(DD+key+'.html',title,heading('Printable resource',title,'Read, print, or adapt this resource.')+section('<div class="prose">'+html+link(key+'.pdf','Download PDF')+'</div>'),'downloads')
  docs+='<article class="download"><div><h3>'+title+'</h3></div><div class="actions">'+link('@@'+DD+key+'.pdf','Download PDF','button small')+link('@@'+DD+key+'.html','Read accessible HTML','button ghost small')+'</div></article>'
 sourcehtml=''.join('<article class="card"><h3>'+link(x['url'],x['name'],'',True)+'</h3><p>'+e(x['description'])+'</p></article>' for x in d['sources'])
 show('resources.html','Coaching resources and handouts',heading('Resources','Keep the conversation going.','Observation guide, coaching protocol, sprint plan, reflection, and original sources.')+section('<p><img src="@@assets/images/coaching-session-qr.svg" width="150" height="150" alt="QR code for Coaching That Clicks resources"></p><p>Session link: <a class="source-link" href="https://mglearn.github.io/tcea27/sessions/coaching-that-clicks/">mglearn.github.io/tcea27/sessions/coaching-that-clicks/</a></p><div class="download-list">'+docs+'</div><h2>Original sources</h2><div class="grid two">'+sourcehtml+'</div><p>'+link('https://mguhlin.org/resources/infographics/','Browse infographics and frameworks','',True)+'</p><h2>Presenter resources</h2><p>Protected facilitator plan, preparation checklist, and presentation. Unlocking is local to your browser.</p><div class="actions">'+link('presenter-guide.html','Open presenter guide')+link('presenter-webdeck.html','Open presenter deck','button ghost')+'</div>'+evidence))
 p=R/'downloads.html';text=p.read_text();addition=section('<h2>Coaching That Clicks resources</h2><p>Observation guide, Notice-Wonder-Next, micro-coaching sprint, ACE reflection, and conference submission.</p>'+link(SP+'resources.html','Open the coaching toolkit'));p.write_text(text.replace('<section class="print-reflection',addition+'<section class="print-reflection',1))
 print('Built Coaching That Clicks: seven public sections and five PDF/HTML handouts.')
